<?php
require_once __DIR__ . '/../config/database.php'; require_login(); if ((current_user()['role'] ?? '') !== 'admin') redirect('dashboard.php');
if ($_SERVER['REQUEST_METHOD'] === 'POST' && verify_csrf($_POST['csrf'] ?? null)) { $version = trim($_POST['version'] ?? ''); $pdo = db(); $pdo->beginTransaction(); try { $pdo->exec("UPDATE ml_models SET status='archived'"); $pdo->exec("UPDATE dataset_versions SET is_active=0"); $activate = $pdo->prepare("UPDATE ml_models SET status='active' WHERE version_name=?"); $activate->execute([$version]); $pdo->prepare('UPDATE dataset_versions SET is_active=1 WHERE version_name=?')->execute([$version]); $pdo->commit(); } catch (Throwable $exception) { $pdo->rollBack(); } }
$models = db()->query('SELECT * FROM ml_models ORDER BY created_at DESC')->fetchAll(); $title = 'Model versions'; require __DIR__ . '/../includes/header.php'; ?><div class="container py-5"><div class="eyebrow">Admin · model registry</div><h1 class="section-title mb-4">Versions with receipts.</h1><div class="panel table-responsive"><table class="table align-middle"><thead><tr><th>Version</th><th>Type</th><th>Target</th><th>Metrics</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($models as $model): $metrics = json_decode($model['metrics'] ?? '{}', true) ?: []; ?><tr><td><strong><?= e($model['version_name']) ?></strong><br><small class="text-muted"><?= e($model['created_at']) ?></small></td><td><?= e($model['model_type']) ?></td><td><?= e($model['target_name']) ?></td><td><?= isset($metrics['accuracy']) ? round($metrics['accuracy'] * 100, 2) . '%' : 'n/a' ?></td><td><span class="badge text-bg-<?= $model['status'] === 'active' ? 'success' : 'light' ?>"><?= e($model['status']) ?></span></td><td><?php if ($model['status'] !== 'active'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="version" value="<?= e($model['version_name']) ?>"><button class="btn btn-sm btn-outline-dark rounded-pill">Activate</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$models): ?><p class="text-muted mb-0">No trained models yet. Install PhpSpreadsheet and train the primary dataset.</p><?php endif; ?></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>